public WebXml getWebXml(FacesContext context) {
	WebXml webXml = WebXml.getInstance(context);
	if (null == webXml) {
		throw new FacesException(
				"Resources framework is not initialised, check web.xml for Filter configuration");
	}
	return webXml;
}

